          </div>
          {map.get(root.id)?.children.map((child) => (
            <div
              key={child.id}
              onClick={() => onSelect(child.id)}
              style={{
                padding: '8px 20px 8px 36px',
                cursor: 'pointer',
                color: selectedId === child.id ? 'var(--color-primary)' : 'var(--color-text-tertiary)',
