        </div>

        <div style={{ padding: 20 }}>
          <div style={{ fontSize: 15, fontWeight: 600, color: 'var(--color-text-secondary)', marginBottom: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {`商品SKU-${product.skuId}`}
