          <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, marginBottom: 16 }}>
            <span style={{ fontSize: 28, fontWeight: 800, color: 'var(--color-primary)', textShadow: '0 0 20px rgba(var(--color-primary-rgb), 0.3)' }}>
