import { Input, Select, DatePicker, Button, Modal, ConfigProvider, Popconfirm } from 'antd'
import { DownloadOutlined, DeleteOutlined, StarOutlined, TrophyOutlined, BookOutlined } from '@ant-design/icons'
import zhCN from 'antd/locale/zh_CN'
import dayjs from 'dayjs'
import 'dayjs/locale/zh-cn'
import {
  updateProfile,
  listAddresses,
  createAddress,
  updateAddress,
  deleteAddress,
  setDefaultAddress,
} from '@/api/user'
import type { ShippingAddress, CreateAddressRequest, UpdateAddressRequest } from '@/types'
import { getWishlistList, removeWishlist } from '@/api/wishlist'
import type { WishlistItem } from '@/api/wishlist'
import { getUserProfile as getCommunityProfile, getUserPosts, getUserDrafts, getLikedPosts, getMyComments } from '@/api/community'
import type { Post, MyComment } from '@/api/community'
import {
  getUserLevel,
  getExpLogs,
  getLevelConfigs,
  getCheckInStatus,
  getContinuousDays,
} from '@/api/growth'
import type { UserLevelInfo, LevelConfig, ExpLogRecord } from '@/api/growth'
import { useAuthStore } from '@/stores/auth'
import {
  sendDeletionCode,
  applyAccountDeletion,
  cancelAccountDeletion,
  getAccountDeletionStatus,
  type AccountDeletionStatus,
} from '@/api/wish'
import { uploadFile } from '@/api/file'
import s from './UserCenter.module.css'

function ConfirmDialog({
  open,
  title,
  content,
  okText = '确定',
  cancelText = '取消',
  danger = false,
  onOk,
  onCancel,
}: {
  open: boolean
  title: string
  content: string
  okText?: string
  cancelText?: string
  danger?: boolean
  onOk: () => void
  onCancel: () => void
}) {
  if (!open) return null
  return createPortal(
    <div style={{
      position: 'fixed',
      inset: 0,
      background: 'rgba(0, 0, 0, 0.6)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 10000,
      backdropFilter: 'blur(4px)',
    }}>
      <div style={{
        background: 'var(--color-bg-container)',
        border: '1px solid var(--color-border)',
        borderRadius: 16,
        padding: '28px 32px',
        width: 380,
        maxWidth: '90vw',
        boxShadow: '0 8px 32px rgba(0,0,0,0.3), 0 0 60px rgba(var(--color-primary-rgb), 0.08)',
        textAlign: 'center',
      }}>
        <div style={{ fontSize: 18, fontWeight: 600, color: 'var(--color-text-secondary)', marginBottom: 12 }}>{title}</div>
        <div style={{ fontSize: 14, color: 'var(--color-text-secondary)', marginBottom: 24, lineHeight: 1.6 }}>{content}</div>
        <div style={{ display: 'flex', justifyContent: 'center', gap: 12 }}>
          <button type="button" onClick={onCancel} style={{
            padding: '8px 24px',
            border: '1px solid var(--color-border)',
            borderRadius: 8,
            background: 'transparent',
            color: 'var(--color-text-secondary)',
            fontSize: 14,
            cursor: 'pointer',
            transition: 'all 0.2s',
          }}>
            {cancelText}
          </button>
          <button type="button" onClick={onOk} style={{
            padding: '8px 24px',
            border: 'none',
            borderRadius: 8,
            background: danger ? 'var(--color-accent-red)' : 'var(--color-gradient-primary)',
            color: '#fff',
            fontSize: 14,
            fontWeight: 600,
            cursor: 'pointer',
            transition: 'all 0.2s',
            minWidth: 100,
            boxShadow: danger
              ? '0 4px 16px rgba(255, 71, 87, 0.3)'
              : '0 4px 16px rgba(var(--color-primary-rgb), 0.3)',
          }}>
            {okText}
          </button>
        </div>
      </div>
