          rules={[{ required: true, message: '请选择发送对象' }]}
          options={[
            { label: '指定用户', value: 'USER' },
            { label: '全部用户', value: 'ALL' },
            { label: '指定用户组', value: 'GROUP' },
          ]}
        />
        <ProFormDigit
          name="userId"
          label="用户ID"
          min={1}
          fieldProps={{ precision: 0 }}
          tooltip="发送对象为「指定用户」时必填"
        />
        <ProFormSelect
          name="type"
          label="通知类型"
          placeholder="请选择通知类型"
