  featureList: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '28px',
    position: 'relative' as const,
    zIndex: 1,
  },
  featureItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
  },
  featureIcon: {
    width: '44px',
    height: '44px',
    borderRadius: '12px',
    background: 'rgba(var(--color-primary-rgb), 0.1)',
    border: '1px solid rgba(var(--color-primary-rgb), 0.15)',
    display: 'flex',
    alignItems: 'center',
