// ========== 社区活动管理（Sprint 3.5，代理 mall-wish /admin/activity/**） ==========

export type AdminActivityType = 'WORLD_EVENT' | 'FESTIVAL' | 'CITY' | 'WISH_PARTNER'
export type AdminActivityStatus = 'DRAFT' | 'ACTIVE' | 'ENDED' | 'ARCHIVED'
