import request from '@/utils/request'
import type { ApiResponse } from '@/types/api'

export interface SearchUserResult {
  id: number
  nickname: string
  avatar: string
}

export interface FollowUserRawItem {
  id: number
  userId?: number
  nickname: string
  avatar: string
  signature: string
  isFollowed: boolean
  isMutual: boolean
}

export interface PostTag {
  id: number
  name: string
}

export interface Post {
  id: number
  type: string
  title: string
  content: string
  summary: string
  coverImage: string
  images: string[]
  mediaUrls: string[]
  mediaType: string
  videoUrl: string | null
  videoCover: string | null
  authorAvatar: string
  authorNickname: string
  userId: number
  tags: PostTag[]
  productId: number | null
  productName: string | null
  productPrice: number | null
  likeCount: number
  commentCount: number
  collectCount: number
  shareCount: number
  viewCount: number
  isLiked: boolean
  isCollected: boolean
  status: string
  createdAt: string
}

export interface PostComment {
  id: number
  postId: number
  authorAvatar: string
  authorNickname: string
  userId: number
  content: string
  parentId: number | null
  replyToNickname?: string
  replyToUserId?: number
  likeCount: number
  isLiked: boolean
  replies: PostComment[]
  createdAt: string
}

export interface HotTopic {
  id: number | string
  name: string
  postCount: number
  icon?: string
  isHot?: boolean
  isSubscribed?: boolean
}

export type CollectionPostItem = Post & { collectedAt?: string }

export interface UserProfile {
  id: number
  nickname: string
  avatar: string
  signature: string
  level: number
  exp: number
  postCount: number
  followerCount: number
  followingCount: number
  followCount: number
  collectionCount: number
  collectCount: number
  isFollowed: boolean
  isMutual: boolean
  isBlocked: boolean
  badges: Array<{ id: number; name: string; icon: string; description: string }>
}

export interface UserSettings {
  [key: string]: string
}

export function searchUsers(keyword: string) {
  return request.get<ApiResponse<SearchUserResult[]>>('/community/users/search', { params: { keyword } })
}

export function getFollowers(userId: number | string, page = 1, size = 20) {
  return request.get<ApiResponse<FollowUserRawItem[]>>(`/community/users/${userId}/followers`, { params: { page, size } })
}

export function getFollowingList(userId: number | string, page = 1, size = 20) {
