    return request.put<ApiResponse<Post>>(`/community/posts/${postId}`, data, {
      headers: { 'Content-Type': 'multipart/form-data' },
    })
  }
  return request.put<ApiResponse<Post>>(`/community/posts/${postId}`, data)
}

export function deletePost(postId: number | string) {
