  enableAiReply?: boolean
  /** 审核状态（PENDING=审核中，审核通过后才在广场可见） */
  auditStatus?: 'PENDING' | 'APPROVED' | 'REJECTED' | 'AUTO_HIDDEN'
}

export interface WishCreateResult {
  id: number | string
